package ua.battlesim.terrain;

import ua.battlesim.api.HeightField;
import ua.battlesim.api.WaterField;
import ua.battlesim.math.FloatGrid;

import java.util.Arrays;
import java.util.Objects;

/**
 * The base terrain data generated by {@link TerrainGenerator}: a height field,
 * a water field (depth, flow, swamp), a forest-density mask, a baked shade map
 * and the sun direction.
 *
 * <p>Units: metres for positions and sizes; radians for angles; the sun
 * direction is a unit vector in the 3-D world (x east, y up, z south).
 *
 * <p>The {@link FloatGrid} fields are read-only after generation; do not call
 * {@code FloatGrid.set} after the {@code TerrainBase} is returned.
 *
 * <p>Deterministic: the same seed and configuration always produce the same
 * terrain. No wall clock, no unseeded randomness.
 *
 * <p>Immutable record; thread-safe (the referenced grids must be treated as
 * read-only after generation).
 */
public record TerrainBase(
        HeightField height,
        WaterField water,
        FloatGrid forestDensity,
        FloatGrid shade,
        double[] sunDirection
) {
    public TerrainBase {
        Objects.requireNonNull(height, "height");
        Objects.requireNonNull(water, "water");
        Objects.requireNonNull(forestDensity, "forestDensity");
        Objects.requireNonNull(shade, "shade");
        Objects.requireNonNull(sunDirection, "sunDirection");
        if (sunDirection.length != 3) {
            throw new IllegalArgumentException(
                    "sunDirection must have exactly 3 components: " + sunDirection.length);
        }
        for (double d : sunDirection) {
            if (!Double.isFinite(d)) {
                throw new IllegalArgumentException(
                        "sunDirection components must be finite: " + Arrays.toString(sunDirection));
            }
        }
        sunDirection = sunDirection.clone();
    }
}
